import{_ as e,c as p,o as r,ah as i}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"64、【未濟】 坎下離上","description":"周易尚氏學 - 64、【未濟】 坎下離上","frontmatter":{"title":"64、【未濟】 坎下離上","description":"周易尚氏學 - 64、【未濟】 坎下離上"},"headers":[],"relativePath":"classics/shangshi/069.md","filePath":"classics/shangshi/069.md"}'),s={name:"classics/shangshi/069.md"};function t(h,a,l,n,c,d){return r(),p("div",null,[...a[0]||(a[0]=[i('<h1 id="_64、【未濟】-坎下離上" tabindex="-1">64、【未濟】 坎下離上 <a class="header-anchor" href="#_64、【未濟】-坎下離上" aria-label="Permalink to “64、【未濟】 坎下離上”">​</a></h1><p>濟止也。六爻皆當位。止其所而不動。故曰既濟。茲六交皆不當位。不止。故曰未濟。終而止。則其道窮。終而不止。則其道不窮。故既未濟相續而循環。柔得五中故亨。艮為小孤。卦有三艮形。故易林渙之未濟雲。三虎上山。更相喧喚。是以未濟為三艮。故曰三虎上山。茲曰小狐。是以艮為狐。訖說文涸也。乾寶雲。小狐力弱。訖乃可濟今水未涸。故儒其尾。艮為尾也。濡尾故無攸利。按九家坎亦為狐。茲曰小狐曰尾。艮為小為尾。故知取艮象。濟者濟坎水也。</p><p>彖曰。未濟寧。柔得中也。小狐訖濟。未出中也。濡其尾無攸利。不續終也。雖不當位。剛柔應也。</p><p>未出中。言二陷於坎中也。六爻皆不當位。無攸利。然賜柔相應。窮則宜變。變則通。故不續終。申不止之義也。</p><p>象曰。火在水上。未濟。君子以慎辨物居方。</p><p>乾陽物。坤陰物。陰陽各當位。是居方也。陰陽皆不當位。是聚而失其方也。辨而明之。慎其居而擇所處。則無咎矣。故君子以之。</p><p>初六。濡其尾。吝。</p><p>在下故曰尾。濡尾故吝。</p><h3 id="象曰。濡其尾。亦不知極也。" tabindex="-1">象曰。濡其尾。亦不知極也。 <a class="header-anchor" href="#象曰。濡其尾。亦不知極也。" aria-label="Permalink to “象曰。濡其尾。亦不知極也。”">​</a></h3><p>極說文棟也。棟居屋中。故極者中也。濡尾知極。言初在下失中。</p><p>九二。曳春輪。貞吉。</p><p>坎為輪為曳。居中。故貞吉。</p><h3 id="象曰。九二貞吉。中以行正也。" tabindex="-1">象曰。九二貞吉。中以行正也。 <a class="header-anchor" href="#象曰。九二貞吉。中以行正也。" aria-label="Permalink to “象曰。九二貞吉。中以行正也。”">​</a></h3><p>以位言。九二中而不正。茲曰行正。以正釋貞也。非謂位正。</p><p>六三。未濟徵兇。利涉大川。</p><p>不當位。前遇險。故徵兇。徵兇則不能利涉。茲日利涉大川。上下文義反背。朱子疑利上有不字。按象雲位不當。則不利也。缺以俟知者。</p><h3 id="象曰。未濟徵兇。" tabindex="-1">象曰。未濟徵兇。 <a class="header-anchor" href="#象曰。未濟徵兇。" aria-label="Permalink to “象曰。未濟徵兇。”">​</a></h3><p>位不當也承乘皆險。動則必兇。柔居剛。故位不當。</p><p>九四。貞吉。悔亡。震用伐克方。三年有賞於大國。</p><p>坎為鬼。易林觀之既濟雲。班馬還師。是用半震。震為馬為反。既濟三半震。故曰班馬還師。茲易曰震用伐鬼方。亦以四五形震。為易林之所本。震為威武為征伐。坎為三故曰三年。有賞於大國者。言伐鬼方有功。以大國賞之也。蓋以五上半艮為國也。貞吉卜問吉也。高士奇天祿識餘雲。易震用伐鬼方。敦深謂震乃摯伯名。程傳訓為威武。則三年有賞於大國。何人也。以文理言。此說頗勝。而述之者少。</p><h3 id="象曰。貞吉悔亡。志行也。" tabindex="-1">象曰。貞吉悔亡。志行也。 <a class="header-anchor" href="#象曰。貞吉悔亡。志行也。" aria-label="Permalink to “象曰。貞吉悔亡。志行也。”">​</a></h3><p>坎為志。四承乘皆陰。故志行。</p><p>六五。貞吉。無悔。君子之光。</p><p>有孚吉。離為光。五君位。故君子之光。下有應。故有孚吉。</p><h3 id="象曰。君子之光。其暉吉也。" tabindex="-1">象曰。君子之光。其暉吉也。 <a class="header-anchor" href="#象曰。君子之光。其暉吉也。" aria-label="Permalink to “象曰。君子之光。其暉吉也。”">​</a></h3><p>離為大明。故其暉吉。暉。說文光也。</p><p>上九。有孚於飲酒。無咎。濡其首。有孚失是。</p><p>坎為酒。為飲食。上九下履重坎。故有孚於飲酒。有應故無咎。上應在三。三居重坎之中。故亦濡其首。六爻皆有應。故有孚。皆失位。故失是。然不續終之故。正以此也。</p><h3 id="象曰。飲酒濡首。亦不知節也。" tabindex="-1">象曰。飲酒濡首。亦不知節也。 <a class="header-anchor" href="#象曰。飲酒濡首。亦不知節也。" aria-label="Permalink to “象曰。飲酒濡首。亦不知節也。”">​</a></h3><p>上艮為節。節止也。過而不止。故不知節。</p><p>附</p><p>即未濟之卦形。即異於常卦。故所取之象。往往為本卦所無。如曰逐。曰高宗。曰伐。日襦（左系）衣如（左衣）。曰殺。曰祭。曰福。曰大國。曰震。本卦皆無此象。於是虞氏用卦變以求其象。惝恍支離。莫可究潔。然經於九四曰震。且明以四五為震矣。故知其它皆用半象也。易林本之。於觀之既濟雲。班馬還師。震之即濟雲。齒齒（右間）齒齒（上契無大）。兌之既濟雲。積石為山。旅之既濟雲。逐鹿南山。恆之既濟雲。三嫗治民。是皆於既濟取震馬震鹿巽嫗兌齒艮山象。又謙之未濟。千柱百梁。是以艮為樑柱。未濟三艮形。故曰千柱百梁。又渙之未濟。三虎上山。亦以三艮為三虎。又蹇之未濟雲。一口三舌。亦以重兌為三舌。凡易林取象。無不本於易。此用半象。必有所受之。而其詳不傳。由是證施孟梁丘三家易學。其取象皆尚有極繁瑣之口傳。徒以古人尚質。竹書艱難。其所為易傳。皆疏其大義。而不詳其煩瑣。致使象數之細微。皆存之口授。不著竹帛。以傷其方雅。故漢時學易者必有師。非重師。重口授也。口授一絕。後人雖欲知而莫由。幸焦氏易林未亡。吾人可按其辭。抽繹墜象。使易之晦辭。得以復明。易之誤解。俾以復正。不然且終古長夜矣。上經終坎離。坎中爻震艮。離中爻巽兌。是舉坎離而六子具也。下經終既未濟。乾坤具備。而即濟一陽一陰。則震兌也。未濟一陰一陽。則艮巽也。是舉坎離而八卦備也。故以為六十四卦之殿。其卦既無所不包。其象遂父母與六子俱備。故易與易林。於既未濟取象。獨不同歟。</p>',32)])])}const m=e(s,[["render",t]]);export{_ as __pageData,m as default};
